"use server";

// Generated by philote from page /tasks/new. Do not edit.
import { redirect } from "next/navigation";

import { tasks } from "@/lib/api";
import { type FormState, failed, text } from "@/lib/form";
import type { Status } from "@/lib/types";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await tasks.create({
        title: text(data, "title"),
        status: text<Status>(data, "status"),
        due: text(data, "due"),
        project_id: text(data, "project_id"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect("/projects");
}
